		}

		$svg = '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 256 256"><path fill="black" d="' . self::PATHS[ $name ] . '"/></svg>';

		// phpcs:ignore WordPress.PHP.DiscouragedPHPFunctions.obfuscation_base64_encode -- so verlangt es add_menu_page fuer eigene Symbole.
		return 'data:image/svg+xml;base64,' . base64_encode( $svg );
	}

	/**
	 * Ein Symbol als SVG-Markup.
	 *
	 * Rein schmueckend und deshalb fuer Screenreader verborgen. Wo ein Symbol
	 * allein steht, traegt das umgebende Element die Beschriftung.
	 *
	 * @param string $name  Name.
	 * @param int    $size  Kantenlaenge in Pixeln.
	 * @param string $class Zusaetzliche Klasse.
	 * @return string
	 */
	public static function svg( $name, $size = 16, $class = '' ) {
		if ( ! self::exists( $name ) ) {
			return '';
		}

		return sprintf(
			'<svg class="%1$s" width="%2$d" height="%2$d" viewBox="0 0 256 256" fill="currentColor" aria-hidden="true" focusable="false"><path d="%3$s"></path></svg>',
			esc_attr( trim( 'undt-icon ' . $class ) ),
			(int) $size,
			esc_attr( self::PATHS[ $name ] )
		);
	}
}
